'use client';

import { useEffect, useState } from 'react';
import Link from 'next/link';
import { User, Play, BarChart2 } from 'lucide-react';
import UserMenu from '../../components/ui/UserMenu';

export default function DashboardPage() {
    const [name, setName] = useState('');
    const [phone, setPhone] = useState('');

    useEffect(() => {
        const storedName = localStorage.getItem('disc_user_name');
        const storedPhone = localStorage.getItem('disc_user_phone');
        if (storedName) setName(storedName);
        if (storedPhone) setPhone(storedPhone);
    }, []);

    return (
        <main className="min-h-screen flex flex-col items-center p-8 bg-black relative text-white">
            {/* Background Ambience */}
            <div className="fixed inset-0 z-0 pointer-events-none">
                <div className="absolute top-[-20%] left-[-10%] w-[800px] h-[800px] bg-purple-900/10 blur-[150px] rounded-full mix-blend-screen" />
                <div className="absolute bottom-[-20%] right-[-10%] w-[800px] h-[800px] bg-cyan-900/10 blur-[150px] rounded-full mix-blend-screen" />
            </div>

            <nav className="w-full max-w-5xl flex justify-between items-center mb-20 z-10 glass-panel p-4 rounded-full border border-white/5 bg-zinc-900/50">
                <div className="px-4 font-bold text-xl tracking-tighter">
                    DISC <span className="text-cyan-400">Futura</span>
                </div>
                <div className="flex gap-4">
                    <UserMenu />
                </div>
            </nav>

            <div className="z-10 w-full max-w-4xl text-center mb-16">
                <h1 className="text-4xl md:text-6xl font-thin mb-4">
                    Hello, <span className="font-bold text-white capitalize">{name || 'Explorer'}</span>
                </h1>
                <p className="text-zinc-500 text-lg md:text-xl font-light">
                    Ready to discover your true potential?
                </p>
            </div>

            <div className="z-10 grid grid-cols-1 md:grid-cols-2 gap-6 w-full max-w-4xl">
                {/* Start Assessment Card */}
                <div className="group relative p-1 rounded-3xl bg-gradient-to-b from-white/10 to-transparent hover:from-cyan-500/50 hover:to-purple-500/50 transition-all duration-500">
                    <div className="bg-zinc-950 h-full rounded-[20px] p-8 flex flex-col items-start justify-between relative overflow-hidden">
                        <div className="absolute top-0 right-0 p-8 opacity-10 group-hover:opacity-20 transition-opacity">
                            <Play size={100} />
                        </div>

                        <div>
                            <div className="w-12 h-12 rounded-full bg-cyan-500/20 flex items-center justify-center text-cyan-400 mb-6">
                                <Play size={24} fill="currentColor" />
                            </div>
                            <h2 className="text-2xl font-bold mb-2 text-white group-hover:text-cyan-200 transition-colors">Start Assessment</h2>
                            <p className="text-zinc-500 leading-relaxed font-light">
                                Begin the 40-question analysis to uncover your behavioral profile. Takes about 5-10 minutes.
                            </p>
                        </div>

                        <Link
                            href="/assessment"
                            className="mt-8 px-6 py-3 rounded-xl bg-white text-black font-semibold hover:scale-105 transition-transform w-full text-center"
                        >
                            Start Now
                        </Link>
                    </div>
                </div>

                {/* Profile / History Card */}
                <div className="group relative p-1 rounded-3xl bg-gradient-to-b from-white/10 to-transparent hover:from-purple-500/50 hover:to-pink-500/50 transition-all duration-500">
                    <div className="bg-zinc-950 h-full rounded-[20px] p-8 flex flex-col items-start justify-between relative overflow-hidden">
                        <div className="absolute top-0 right-0 p-8 opacity-10 group-hover:opacity-20 transition-opacity">
                            <User size={100} />
                        </div>

                        <div>
                            <div className="w-12 h-12 rounded-full bg-purple-500/20 flex items-center justify-center text-purple-400 mb-6">
                                <User size={24} />
                            </div>
                            <h2 className="text-2xl font-bold mb-2 text-white group-hover:text-purple-200 transition-colors">My Profile</h2>
                            <p className="text-zinc-500 leading-relaxed font-light">
                                Update your personal details or view your unique ID: <span className="font-mono text-zinc-400">{phone}</span>
                            </p>
                        </div>

                        <Link
                            href="/profile"
                            className="mt-8 px-6 py-3 rounded-xl border border-white/20 text-white font-semibold hover:bg-white/10 transition-colors w-full text-center"
                        >
                            Edit Profile
                        </Link>
                    </div>
                </div>
            </div>
        </main>
    );
}
