'use client';

import { useState, useRef, useEffect } from 'react';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { User, LogOut, ChevronDown } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';

export default function UserMenu() {
    const [isOpen, setIsOpen] = useState(false);
    const timeoutRef = useRef(null);
    const router = useRouter();

    const [user, setUser] = useState({ name: '', phone: '', email: '' });

    useEffect(() => {
        // Hydrate from local storage on mount
        setUser({
            name: localStorage.getItem('disc_user_name') || 'User',
            phone: localStorage.getItem('disc_user_phone') || '',
            email: localStorage.getItem('disc_user_email') || '' // If we store email
        });
    }, []);

    const handleMouseEnter = () => {
        if (timeoutRef.current) clearTimeout(timeoutRef.current);
        setIsOpen(true);
    };

    const handleMouseLeave = () => {
        timeoutRef.current = setTimeout(() => {
            setIsOpen(false);
        }, 300); // Small delay to prevent flickering
    };

    const handleLogout = () => {
        // Clear session
        localStorage.removeItem('disc_user_id');
        localStorage.removeItem('disc_user_name');
        localStorage.removeItem('disc_user_phone');
        localStorage.removeItem('disc_user_email');

        router.push('/login');
    };

    return (
        <div
            className="relative z-50"
            onMouseEnter={handleMouseEnter}
            onMouseLeave={handleMouseLeave}
        >
            <button className="flex items-center gap-2 p-2 rounded-full hover:bg-white/10 transition-colors group">
                <div className="w-10 h-10 rounded-full bg-gradient-to-tr from-cyan-500 to-blue-500 flex items-center justify-center text-white shadow-lg">
                    <User size={20} />
                </div>
            </button>

            <AnimatePresence>
                {isOpen && (
                    <motion.div
                        initial={{ opacity: 0, y: 10, scale: 0.95 }}
                        animate={{ opacity: 1, y: 0, scale: 1 }}
                        exit={{ opacity: 0, y: 10, scale: 0.95 }}
                        transition={{ duration: 0.2 }}
                        className="absolute right-0 top-full mt-2 w-72 p-1 rounded-2xl glass-panel border border-white/10 bg-zinc-900/95 shadow-[0_10px_40px_rgba(0,0,0,0.5)] backdrop-blur-xl overflow-hidden"
                    >
                        <div className="p-4 border-b border-white/5 bg-white/5">
                            <h3 className="font-bold text-white mb-1">{user.name || 'Explorer'}</h3>
                            <p className="text-xs text-zinc-400 font-mono">{user.phone}</p>
                            {user.email && <p className="text-xs text-zinc-500 truncate">{user.email}</p>}
                        </div>

                        <div className="p-2">
                            <Link
                                href="/profile"
                                className="flex items-center gap-3 w-full p-3 rounded-xl hover:bg-white/5 text-zinc-300 hover:text-white transition-colors text-sm"
                            >
                                <User size={16} />
                                My Profile
                            </Link>

                            <button
                                onClick={handleLogout}
                                className="flex items-center gap-3 w-full p-3 rounded-xl hover:bg-red-500/10 text-red-400 hover:text-red-300 transition-colors text-sm text-left"
                            >
                                <LogOut size={16} />
                                Logout
                            </button>
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>
        </div>
    );
}
